	local result3 = result2:gsub(",", "")
	local result4 = result3:gsub("_", "")
	local result5 = result4:match("([%d%.]+%s*[kKmMbBtTqQ]?)%s*[Kk]%.?[Gg]")
	local result6 = string.lower(tostring(result5)):gsub("[%s,_]", "")
	result6:sub(-2)
	result6:sub(-1)
	end

